// Generated by OrchestKit Claude Plugin
// Created: 2026-08-21

// Guards the "rate limit response headers" recovery. The audit scored this
// Partial: "REST rate-limit headers documented in OpenAPI spec, but not
// observed on a live response."
//
// Root cause, measured against production on 2026-08-21:
//   curl -sD- .../api/search  → ratelimit-limit: 120        (route self-limits)
//   curl -sD- .../api/health  → no ratelimit-* header at all
// The discovery surfaces a scanner probes first (/openapi.json, /llms.txt, the
// eight /.well-known cards, /api/health) are `revalidate = false` handlers that
// run at BUILD time, so no per-request header can come from inside them.
// Middleware now meters them. These tests pin both halves of that split: full
// coverage, and no double counting.

import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { classifyAgentSurface } from "@/lib/agent-surface";
import {
	canonicalRoute,
	checkRateLimit,
	middlewareShouldMeter,
	rateLimitHeaders,
	RATE_LIMIT,
	SELF_LIMITED_ROUTES,
} from "@/lib/rate-limit";

const APP = resolve(__dirname, "../app");

/** Every route.ts under app/ whose source calls checkRateLimit itself. */
function selfLimitingRoutesOnDisk(): string[] {
	const found: string[] = [];
	function walk(dir: string, urlPath: string) {
		for (const entry of readdirSync(dir, { withFileTypes: true })) {
			const abs = join(dir, entry.name);
			if (entry.isDirectory()) {
				// Skip dynamic segments in the URL we reconstruct: the counter key is
				// the static prefix ([token] under /api/jobs is one route family).
				const seg = entry.name.startsWith("[") ? "" : `/${entry.name}`;
				walk(abs, `${urlPath}${seg}`);
			} else if (entry.name === "route.ts") {
				if (readFileSync(abs, "utf8").includes("checkRateLimit(")) {
					found.push(urlPath || "/");
				}
			}
		}
	}
	walk(APP, "");
	return [...new Set(found)].sort();
}

describe("SELF_LIMITED_ROUTES matches the source tree", () => {
	it("lists exactly the routes that call checkRateLimit themselves", () => {
		// Drift here is silent and expensive in BOTH directions: a route added to
		// the list but not self-limiting loses its headers entirely, and a route
		// self-limiting but missing from the list gets counted twice, halving the
		// published 120/min ceiling without any error.
		expect(selfLimitingRoutesOnDisk()).toEqual([...SELF_LIMITED_ROUTES].sort());
	});
});

describe("middlewareShouldMeter", () => {
	it("meters the prerendered agent surfaces the audit could not observe", () => {
		for (const p of [
			"/api/health",
			"/api/openapi",
			"/openapi.json",
			"/llms.txt",
			"/llms-full.txt",
			"/.well-known/api-catalog",
			"/.well-known/agent-card.json",
			"/.well-known/mcp/server-card.json",
			"/api/mcp",
			"/api/md/foundations/overview",
		]) {
			expect(middlewareShouldMeter(p), `should be metered: ${p}`).toBe(true);
		}
	});

	it("does NOT meter the routes that meter themselves, via any alias", () => {
		for (const p of [
			"/api/search",
			"/api/v1/search",
			"/api/ask",
			"/ask",
			"/api/md/batch",
			"/api/jobs/abc123",
		]) {
			expect(middlewareShouldMeter(p), `must not double-count: ${p}`).toBe(false);
		}
	});

	it("never meters our own analytics sink, the PostHog proxy, or Next assets", () => {
		// These are browser traffic wearing an API-shaped URL. Metering them would
		// let ordinary page views trip an abuse brake meant for API clients.
		for (const p of ["/api/analytics", "/ingest/e/", "/ingest/static/array.js", "/_next/data/x.json"]) {
			expect(middlewareShouldMeter(p), `must stay unmetered: ${p}`).toBe(false);
		}
	});
});

describe("canonicalRoute", () => {
	it("collapses the versioned alias onto the endpoint it aliases", () => {
		expect(canonicalRoute("/api/v1/search")).toBe("/api/search");
		expect(canonicalRoute("/api/v1/md/x")).toBe("/api/md/x");
	});

	it("collapses the bare rewrites onto their handlers", () => {
		expect(canonicalRoute("/ask")).toBe("/api/ask");
		expect(canonicalRoute("/mcp")).toBe("/api/mcp");
	});

	it("leaves an ordinary path alone", () => {
		expect(canonicalRoute("/api/health")).toBe("/api/health");
	});
});

describe("every agent surface ends up covered by exactly one counter", () => {
	it("each classified agent surface is metered by middleware or self-limits", () => {
		const surfaces = [
			"/.well-known/agent-card.json",
			"/openapi.json",
			"/llms.txt",
			"/api/md/x",
			"/api/search",
			"/ask",
			"/api/mcp",
		];
		for (const p of surfaces) {
			expect(classifyAgentSurface(p)).not.toBeNull();
			const byMiddleware = middlewareShouldMeter(p);
			const bySelf = SELF_LIMITED_ROUTES.includes(canonicalRoute(p));
			// Exactly one, never both (double count), never neither (no headers).
			expect(byMiddleware !== bySelf, `coverage gap or overlap at ${p}`).toBe(true);
		}
	});
});

describe("rateLimitHeaders", () => {
	function req(ip: string) {
		return new Request("https://orchestkit.yonyon.ai/api/health", {
			headers: { "x-real-ip": ip },
		});
	}

	it("emits both the IETF names and the legacy X- twins", () => {
		const headers = rateLimitHeaders(checkRateLimit(req("1.2.3.4"), "/t-names"));
		for (const key of [
			"RateLimit-Policy",
			"RateLimit-Limit",
			"RateLimit-Remaining",
			"RateLimit-Reset",
			"X-RateLimit-Limit",
			"X-RateLimit-Remaining",
			"X-RateLimit-Reset",
		]) {
			expect(headers[key], `missing ${key}`).toBeDefined();
		}
		expect(headers["RateLimit-Policy"]).toBe(`${RATE_LIMIT};w=60`);
	});

	it("counts down per IP and reports `limited` past the ceiling", () => {
		const route = "/t-countdown";
		const first = checkRateLimit(req("9.9.9.9"), route);
		expect(first.limited).toBe(false);
		expect(first.remaining).toBe(RATE_LIMIT - 1);
		for (let i = 1; i < RATE_LIMIT; i++) checkRateLimit(req("9.9.9.9"), route);
		const atLimit = checkRateLimit(req("9.9.9.9"), route);
		expect(atLimit.limited).toBe(true);
		expect(atLimit.remaining).toBe(0);
		// A different IP is unaffected, the window is per IP, per route.
		expect(checkRateLimit(req("8.8.8.8"), route).limited).toBe(false);
	});
});

// A header that is sent but not exposed is invisible to exactly the client class
// this site advertises support for. next.config.mjs already sets
// `Access-Control-Allow-Origin: *` with the comment "so cross-origin (incl.
// browser-based) AI agents can actually read /ask, /api/mcp, ...", but CORS only
// reveals six safelisted response headers to a cross-origin reader. Without an
// explicit expose list, a browser agent gets `null` from every RateLimit-*
// lookup while curl sees them, with no error on either side.
describe("rate-limit headers are readable cross-origin", () => {
	const config = readFileSync(resolve(__dirname, "../next.config.mjs"), "utf8");
	const exposed =
		config.match(/Access-Control-Expose-Headers[\s\S]{0,900}?\.join\(", "\)/)?.[0] ?? "";

	it("declares an Access-Control-Expose-Headers list at all", () => {
		expect(exposed, "no Access-Control-Expose-Headers block found").not.toBe("");
	});

	it("exposes every header rateLimitHeaders() emits", () => {
		const emitted = Object.keys(
			rateLimitHeaders({ limited: false, remaining: 1, resetSeconds: 60 }),
		);
		for (const name of emitted) {
			expect(exposed, `RateLimit header not exposed to CORS: ${name}`).toContain(
				`"${name}"`,
			);
		}
	});

	it("exposes Retry-After, so a 429 is actionable in a browser", () => {
		expect(exposed).toContain('"Retry-After"');
	});

	it("exposes the policy-signalling headers too", () => {
		for (const name of ["Link", "Deprecation", "Sunset"]) {
			expect(exposed, `policy header not exposed: ${name}`).toContain(`"${name}"`);
		}
	});
});
